		const files = await loadSystemPromptFiles(options({ cwd, agentDir }));
		expect(files.system?.label).toBe(".pi/SYSTEM.md");
		expect(files.append).toStrictEqual({
			label: "agent_dir/APPEND_SYSTEM.md",
			content: "User append.",
		});
	});

